  const sessionId = req.cookies.session_id || crypto.randomUUID();
  sessions[sessionId] = {
    ...sessions[sessionId],
    lastAccess: Date.now(),
    data: req.body || {},
    headers: req.headers,
  };
  req.session = sessions[sessionId];
  res.cookie('session_id', sessionId);
  next();
